// --- UTILS ---
const normalizeCurrentReadText = (value?: string) =>
  String(value || '')
    .toLowerCase()
    .trim()
    .replace(/[^\p{L}\p{N}\s]/gu, '')
    .replace(/\s+/g, ' ');

const truthyFlag = (value: any) =>
  value === true || String(value || '').trim().toLowerCase() === 'true' || String(value || '').trim().toLowerCase() === 'yes';

const bookAvailabilityFromBook = (book: Partial<Book> | any) => {
  const swapMode = String(book?.swap_mode || book?.swapType || '').toLowerCase();
  const rentSaleMode = String(book?.rent_sale_mode || '').toLowerCase();
  const permanentExchange = truthyFlag(book?.permanent_exchange) || swapMode === 'permanent' || (truthyFlag(book?.available_for_swap) && !swapMode);
  const temporaryExchange = truthyFlag(book?.temporary_exchange) || swapMode === 'temporary';
  const rent = truthyFlag(book?.rent) || rentSaleMode === 'rent';
  const sell = truthyFlag(book?.sell) || rentSaleMode === 'sell' || rentSaleMode === 'sale';
  return { permanentExchange, temporaryExchange, rent, sell };
};

const bookHasPublicUse = (book: Partial<Book> | any) => {
  const flags = bookAvailabilityFromBook(book);
  return flags.permanentExchange || flags.temporaryExchange || flags.rent || flags.sell;
};

const bookHasLibraryVisibility = (book: Partial<Book> | any) =>
  truthyFlag(book?.favourite) || truthyFlag(book?.currently_reading) || truthyFlag(book?.tbr) || truthyFlag(book?.bookshelf) || bookHasPublicUse(book);

const readingStatusBadgesFromBook = (book: Partial<Book> | any) => {
  const availability = bookAvailabilityFromBook(book);
  return [
    truthyFlag(book?.favourite) ? 'Favourite' : '',
    truthyFlag(book?.currently_reading) ? 'Currently Reading' : '',
    truthyFlag(book?.tbr) ? 'TBR' : '',
    truthyFlag(book?.bookshelf) ? 'Bookshelf' : '',
    availability.permanentExchange ? 'Permanent Exchange' : '',
    availability.temporaryExchange ? 'Temporary Exchange' : '',
    availability.rent ? 'Rent' : '',
    availability.sell ? 'Sell' : ''
  ].filter(Boolean);
};
