const eventVideoFields = [
  'galleryVideos',
  'videoUrls',
  'videos',
  'driveFolderUrl',
  'galleryFolderLink',
] as const;

const uniqueUrls = (urls: string[]) => {
  const seen = new Set<string>();
  return urls.filter(url => {
    const key = url.trim();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const collectEventFieldUrls = (event: Partial<SwapEvent>, fields: readonly string[]) => {
  return uniqueUrls(fields.flatMap(field => splitEventMedia((event as any)[field])));
};

const isLikelyVideoUrl = (url: string) => {
  const value = String(url || '').toLowerCase();
  return /\.(mp4|mov|webm|m4v)(\?|#|$)/.test(value) || value.includes('youtube.com') || value.includes('youtu.be') || value.includes('vimeo.com');
};

const getEventCoverImage = (event: Partial<SwapEvent>) => {
  const images = collectEventFieldUrls(event, eventCoverImageFields).filter(url => !isLikelyVideoUrl(url));
  return normalizeImageUrl(images[0] || '');
};

const hasEventVideoMedia = (event: Partial<SwapEvent>) => collectEventFieldUrls(event, eventVideoFields).length > 0;

const isPastOrCompletedEvent = (event: Partial<SwapEvent>) => {
  const status = String(event.status || '').trim().toLowerCase();
  const eventDate = new Date(String((event as any).date || (event as any).eventDate || (event as any).EventDate || ''));
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return status === 'completed' || (!isNaN(eventDate.getTime()) && eventDate < today);
};

const isPublicEventGallery = (event: Partial<SwapEvent>) => {
  return isPastOrCompletedEvent(event);
};

const getEventGalleryMedia = (event: Partial<SwapEvent>) => {
  const photos = collectEventFieldUrls(event, eventMediaFields)
    .filter(url => !isLikelyVideoUrl(url))
    .map(url => normalizeImageUrl(url))
    .filter(Boolean)
    .map(url => ({ type: 'photo' as const, url }));
  const videos = collectEventFieldUrls(event, eventVideoFields)
    .map(url => ({ type: 'video' as const, url: url.trim() }))
    .filter(item => item.url);
  const allItems = [...photos, ...videos];
  const seen = new Set<string>();
  return allItems.filter(item => {
    const key = `${item.type}:${item.url.toLowerCase()}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

