const extractDriveFileId = (url: string) => {
  if (!url) return '';
  const patterns = [
    /\/file\/d\/([^/]+)/,
    /\/d\/([^/]+)/,
    /id=([^&]+)/,
    /open\?id=([^&]+)/,
    /uc\?export=view&id=([^&]+)/,
    /drive\.google\.com\/thumbnail\?id=([^&]+)/,
    /drive\.google\.com\/viewer\?id=([^&]+)/
  ];

  const value = String(url).trim();
  for (const pattern of patterns) {
    const match = value.match(pattern);
    if (match?.[1]) return match[1];
  }
  
  if (value.length >= 25 && value.length <= 45 && !value.includes('/') && !value.includes('.') && !value.includes(':')) {
    return value;
  }
  
  return '';
};

const normalizeBookImageUrl = (url: string) => {
  if (!url) return '';
  const fileId = extractDriveFileId(url);
  if (fileId) {
    // Using thumbnail endpoint is more reliable for embedding in <img> tags
    return `https://drive.google.com/thumbnail?id=${fileId}&sz=w800`;
  }
  return url.trim();
};

// Empty cells that finish the last shelf so its plank runs the full width.
// One set per column count (2 phone / 3 tablet / 4 laptop); CSS shows only
// the set that matches the current layout (see .ss-shelf in index.css).
const shelfFillers = (count: number, keyPrefix: string) =>
  [2, 3, 4].flatMap((cols) =>
    Array.from({ length: (cols - (count % cols)) % cols }).map((_, i) => (
      <span key={`${keyPrefix}-${cols}-${i}`} className={`ss-shelf__book ss-shelf__book--empty ss-shelf__book--fill${cols}`} aria-hidden="true" />
    )),
  );

const getBookImages = (book: Book | any) => {
  if (!book) return [];
  const rawUrls = book.imageUrls || book.imageUrl || book.imageurl || '';
  if (!rawUrls) return [];
  
  // Split by pipe or comma, potentially nested
  const urls = String(rawUrls)
    .split('|')
    .flatMap(part => part.split(','))
    .map(url => url.trim())
    .filter(Boolean);
  
  return urls.map(url => normalizeBookImageUrl(url));
};
const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
};

// --- LISTING PHOTOS ---
// Shrinking photos in the browser before upload lives in
// utils/imageCompress.ts (shared with the custom mug enquiry).

/* ── Café story media ────────────────────────────────────────────────
   Stories are the largest thing this app ever posts, and the ceiling is
   not ours to choose: Vercel refuses a serverless request body over
   4.5MB, and base64 inflates a file by roughly a third. So the honest
   limit on a story is about 3MB of actual file, whatever the phone's
   camera would like to produce.

   A photo is re-encoded to fit — a 12MP camera shot lands comfortably
   under the cap after this. A video cannot be transcoded in the browser,
   so it is measured and refused with a specific message rather than
   uploaded into a 413 the reader would never understand.
   ──────────────────────────────────────────────────────────────────── */
const STORY_PHOTO_MAX_EDGE = 1280;
const STORY_PHOTO_QUALITY = 0.8;
const STORY_PHOTO_MAX_BYTES = 2 * 1024 * 1024;
const STORY_VIDEO_MAX_BYTES = 3 * 1024 * 1024;

const prepareStoryMedia = async (file: File): Promise<string> => {
  if (file.type.startsWith('video/')) {
    if (file.size > STORY_VIDEO_MAX_BYTES) {
      throw new Error(
        'That clip is too large to post. Stories take videos up to about 3MB — roughly ten seconds. Try trimming it, or post a photo instead.'
      );
    }
    return fileToBase64(file);
  }

  if (!file.type.startsWith('image/')) {
    throw new Error('Stories take photos and short clips. That file is neither.');
  }

  if (typeof document === 'undefined') return fileToBase64(file);

  const approxBytes = (url: string) => Math.ceil((url.length - (url.indexOf(',') + 1)) * 0.75);

  /**
   * Decodes the file. Tries createImageBitmap first: on Android it
   * decodes off the main thread and copes with large photos that make an
   * HTMLImageElement give up, which is the likeliest reason a perfectly
   * ordinary photo was being rejected on a phone.
   */
  const decode = async (): Promise<{ source: CanvasImageSource; w: number; h: number }> => {
    if (typeof createImageBitmap === 'function') {
      try {
        const bitmap = await createImageBitmap(file);
        if (bitmap.width > 0 && bitmap.height > 0) {
          return { source: bitmap, w: bitmap.width, h: bitmap.height };
        }
      } catch {
        // Fall through to the <img> path.
      }
    }
    const img = await loadImageElement(file);
    // A zero-dimension decode is a failure wearing a success's clothes:
    // the old code carried on and produced a 1x1 pixel "photo".
    if (!img.naturalWidth || !img.naturalHeight) throw new Error('decode-empty');
    return { source: img, w: img.naturalWidth, h: img.naturalHeight };
  };

  /** Re-encodes at a given long edge. Returns '' if the canvas refuses. */
  const encodeAt = (
    source: CanvasImageSource, natW: number, natH: number, maxEdge: number
  ): string => {
    const longEdge = Math.max(natW, natH);
    const scale = longEdge > maxEdge ? maxEdge / longEdge : 1;
    const width = Math.max(1, Math.round(natW * scale));
    const height = Math.max(1, Math.round(natH * scale));

    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    if (!ctx) return '';
    // White ground so a transparent PNG doesn't flatten to black.
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, width, height);
    ctx.drawImage(source, 0, 0, width, height);

    let quality = STORY_PHOTO_QUALITY;
    let url = canvas.toDataURL('image/jpeg', quality);
    while (approxBytes(url) > STORY_PHOTO_MAX_BYTES && quality > 0.35) {
      quality -= 0.15;
      url = canvas.toDataURL('image/jpeg', quality);
    }
    return approxBytes(url) <= STORY_PHOTO_MAX_BYTES ? url : '';
  };

  let decoded;
  try {
    decoded = await decode();
  } catch (err) {
    // The browser genuinely cannot read this file. Say what was tried, so
    // a report of "it didn't work" is actionable instead of a mystery.
    console.error('[story] decode failed', err, { type: file.type, size: file.size });
    throw new Error(
      `We couldn’t open that ${file.type || 'file'}. Try a JPG or PNG from your gallery.`
    );
  }

  // Step the size down rather than only the quality. A dense photo that
  // will not fit at 1280px fits easily at 720, and a slightly smaller
  // story is much better than a refused one.
  for (const edge of [STORY_PHOTO_MAX_EDGE, 1024, 800, 640]) {
    try {
      const url = encodeAt(decoded.source, decoded.w, decoded.h, edge);
      if (url) return url;
    } catch (err) {
      console.error('[story] encode failed at ' + edge + 'px', err);
    }
  }

  // Last resort: the original bytes, if they are already small enough.
  if (file.size <= STORY_PHOTO_MAX_BYTES) return fileToBase64(file);

  throw new Error('We couldn’t get that photo small enough to post. Try one taken at a lower resolution.');
};

const formatSubscriptionDate = (dateStr: string | undefined | null) => {
  if (!dateStr) return '—';
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr || 'TBD';
    return d.toLocaleDateString('en-GB', {
      day: 'numeric',
      month: 'short',
      year: 'numeric'
    }) + `, ` + d.toLocaleTimeString('en-GB', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    }).toUpperCase();
  } catch (e) {
    return 'TBD';
  }
};

const getSubStart = (sub: any) => sub?.subscriptionStartDate || sub?.subscriptionStar || sub?.subscriptionStart || '';
const getSubExpiry = (sub: any) => sub?.subscriptionExpiry || sub?.subscriptionExpi || sub?.subscriptionExp || '';
const haversineDistance = (lat1: number, lon1: number, lat2: number, lon2: number) => {
  const R = 6371; // km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = 
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

